// QA-only acceptance gap probes: actual block WriteVar rejection and late ACK replay prevention.
use field_flow::{config::Config,domain::id,fixture::Fixture,infrastructure::{state::{self,State,StateTask},s7_int_pdu::{Session,Operation,Validated}},runtime::Runtime};
use std::{path::{Path,PathBuf},time::Duration};
use serde_json::{json,Value};
async fn open(c:&Config,dir:&Path,bin:&Path,new:bool)->(Runtime,State,StateTask){if new{state::init(dir,"execute",&c.instance_id).unwrap()}let(s,t)=State::open(dir,"execute",&c.instance_id,&id()).unwrap();let r=Runtime::start(c,dir,bin,s.clone()).unwrap();let end=tokio::time::Instant::now()+Duration::from_secs(4);while r.owners["plc_demo"].health().state!="ready"{assert!(tokio::time::Instant::now()<end);tokio::time::sleep(Duration::from_millis(3)).await;}(r,s,t)}
async fn iteration(c:&Config,r:&Runtime,s:&State)->field_flow::Result<()>{field_flow::app::demo01::iteration(&c.flows[0],&c.plcs[0],&field_flow::services::Http::new(&c.http).unwrap(),&r.owners["plc_demo"],s,&r.stop,&mut field_flow::domain::Clock::default()).await}
async fn close(r:Runtime,s:State,t:StateTask){let _=r.shutdown(15000).await;drop(s);t.join().await.unwrap();}
fn readback()->[u8;16]{use rust_snap7::{S7Client,InternalParam as P,InternalParamValue as V};let c=S7Client::create();c.set_param(P::RemotePort,V::U16(31102)).unwrap();c.connect_to("127.0.0.1",0,1).unwrap();let mut s=Session::default();let mut result=[0;16];for o in (0..16).step_by(2){match s.exchange(&c,1,o as u32,Operation::Read).unwrap(){Validated::Read(v)=>result[o..o+2].copy_from_slice(&v.value().to_be_bytes()),_=>panic!()}}c.disconnect().unwrap();drop(c);result}
fn main(){let q=PathBuf::from(std::env::args().nth(1).unwrap());let bin=PathBuf::from(std::env::args().nth(2).unwrap());tokio::runtime::Builder::new_multi_thread().worker_threads(4).enable_all().build().unwrap().block_on(async{
let mut f=Fixture::start(&q.join("rust-formal-target/debug/ff-fixture")).unwrap();let c=Config::load(Path::new("config/loopback.yaml")).unwrap();let dir=q.join("rust-precall-health");std::env::set_var("FF_TEST_CHILD_BARRIER","1");let(r,s,t)=open(&c,&dir,&bin,true).await;std::env::remove_var("FF_TEST_CHILD_BARRIER");f.command("precall-health",json!(42));let cc=c.clone();let ss=s.clone();let owner=r.owners["plc_demo"].clone();let stop=r.stop.clone();let job=tokio::spawn(async move{field_flow::app::demo01::iteration(&cc.flows[0],&cc.plcs[0],&field_flow::services::Http::new(&cc.http).unwrap(),&owner,&ss,&stop,&mut field_flow::domain::Clock::default()).await});let end=tokio::time::Instant::now()+Duration::from_secs(2);while r.owners["plc_demo"].health().in_flight==0{assert!(tokio::time::Instant::now()<end);tokio::time::sleep(Duration::from_millis(2)).await;}tokio::time::sleep(Duration::from_millis(100)).await;let health=r.owners["plc_demo"].health();let physical=f.snapshot()["writes"].as_u64().unwrap();let durable=state::inspect(&dir).unwrap();let started=std::fs::read_to_string(dir.join("runtime.jsonl")).unwrap().lines().filter(|l|serde_json::from_str::<Value>(l).ok().is_some_and(|v|v["event"]=="driver_call_started")).count();assert_eq!(physical,0);assert_eq!(started,0);r.stop.close().unwrap();let job_result=job.await.unwrap();assert_eq!(job_result.as_ref().unwrap_err(),"canceled");let shutdown=r.shutdown(15000).await;drop(s);t.join().await.unwrap();
let wall=field_flow::domain::now_ms();let mut input:field_flow::domain::Input=serde_json::from_value(json!({"schema_version":1,"source_id":"demo01-feed","ready":true,"command_id":"clock-model","value":42,"issued_at_ms":wall-5000,"expires_at_ms":wall+30000})).unwrap();let intent=input.intent(&c.flows[0],&c.plcs[0]).unwrap().unwrap();let utc_only=intent.validate_time(wall-2000);let drift=field_flow::domain::Clock::default().check(wall-2000);let protocol=f.snapshot();let native=f.native_pid;f.close().unwrap();let report=json!({"precall_barrier":{"health":health,"actual_WriteVar":physical,"driver_call_started_events":started,"durable_before_stop":durable,"after_stop":state::inspect(&dir).unwrap(),"job_result":job_result,"shutdown":shutdown},"clock_counterexample":{"initial_source_age_ms":5000,"wall_jump_ms":-2000,"utc_only_validation":utc_only,"proper_drift_check":drift,"scope":"local arithmetic model plus source control-flow review; host system clock unchanged; not a real wall-clock-jump runtime experiment"},"protocol":protocol,"native_pid":native,"native_exit":0,"fixture_joined":true,"ports_rebound":[31102,31103,31880]});std::fs::write(q.join("rust-clock-health.json"),serde_json::to_vec_pretty(&report).unwrap()).unwrap();println!("{}",report);});std::process::exit(1);}
